export function parseRange(text) {
  const [from, to] = text.split("-");
  return { from: Number(from), to: Number(to) };
}

input.replace:
export function parseRange(text) {
  const [from, to] = text.split("-");
  const fromNum = Number(from);
  const toNum = to ? Number(to) : fromNum;
  return { from: fromNum, to: toNum };
}
